const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Central Valley of California geometry
  const centralValley = ee.Geometry.Polygon([
    [-122.5, 35.0],
    [-122.5, 40.5],
    [-119.0, 40.5],
    [-119.0, 35.0],
    [-122.5, 35.0]
  ]);

  // 2. Define time period
  const startDate = '2022-10-01';
  const endDate = '2023-03-31';

  // 3. Load CHIRPS precipitation data
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate(startDate, endDate)
    .filterBounds(centralValley);

  // Check if collection has data
  const collectionSize = chirps.size().getInfo();
  console.log(`Collection size: ${collectionSize} images`);

  if (collectionSize === 0) {
    console.log('No precipitation data found for the period.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 4. Sum precipitation over the period (mm)
  const totalPrecipMm = chirps.select('precipitation').sum();

  // 5. Calculate statistics
  const stats = totalPrecipMm.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: centralValley,
    scale: 5000,
    maxPixels: 1e9
  }).getInfo();

  const pixelCount = totalPrecipMm.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: centralValley,
    scale: 5000,
    maxPixels: 1e9
  }).getInfo();

  const precipMm = stats.precipitation;
  const pixels = pixelCount.precipitation;

  console.log(`Valid pixels: ${pixels}`);

  if (pixels === 0) {
    console.log('No valid pixels in region.');
    console.log('<answer>C2</answer>');
    return;
  }

  if (precipMm === null || precipMm === undefined || isNaN(precipMm)) {
    console.log('Calculation failed - invalid result.');
    console.log('<answer>C3</answer>');
    return;
  }

  // Convert mm to inches (1 inch = 25.4 mm)
  const precipInches = precipMm / 25.4;

  console.log(`Total precipitation: ${precipMm.toFixed(2)} mm (${precipInches.toFixed(2)} inches)`);
  console.log(`Period: ${startDate} to ${endDate}`);

  // 6. Determine answer
  if (precipInches >= 15.0) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
